db:insert.db:input-parameters:
#[{
                campaignId: vars.campaign.campaign_id,
                executionId: vars.executionId,
                idempotencyKey: vars.idempotencyKey
            }]

set-variable.value:
#[
			        vars.customerRecords flatMap (c) -> [
			            {
			                customer_id: c.customer_id,
			                channel: 'EMAIL',
			                address: c.email,
			                outcome:
			                    if (
			                        c.email_consent == 1
			                        and c.email_suppressed == 0
			                        and c.recent_email_count == 0
			                    )
			                        'ELIGIBLE'
			                    else
			                        'EXCLUDED',
			                exclusion_reason:
			                    if (c.email_consent != 1)
			                        'NO_CONSENT'
			                    else if (c.email_suppressed == 1)
			                        'SUPPRESSED'
			                    else if (c.recent_email_count > 0)
			                        'RECENT_CONTACT'
			                    else
			                        null
			            },
			            {
			                customer_id: c.customer_id,
			                channel: 'SMS',
			                address: c.phone,
			                outcome:
			                    if (
			                        c.sms_consent == 1
			                        and c.recent_sms_count == 0
			                    )
			                        'ELIGIBLE'
			                    else
			                        'EXCLUDED',
			                exclusion_reason:
			                    if (c.sms_consent != 1)
			                        'NO_CONSENT'
			                    else if (c.recent_sms_count > 0)
			                        'RECENT_CONTACT'
			                    else
			                        null
			            },
			            {
			                customer_id: c.customer_id,
			                channel: 'PUSH',
			                address: c.push_token,
			                outcome:
			                    if (
			                        c.push_consent == 1
			                        and c.recent_push_count == 0
			                    )
			                        'ELIGIBLE'
			                    else
			                        'EXCLUDED',
			                exclusion_reason:
			                    if (c.push_consent != 1)
			                        'NO_CONSENT'
			                    else if (c.recent_push_count > 0)
			                        'RECENT_CONTACT'
			                    else
			                        null
			            }
			        ]
			    ]

db:update.db:input-parameters:
#[{

    matchedCount: vars.matchedCount,

    eligibleCount: vars.eligibleCount,

    excludedCount: vars.excludedCount,

    executionId: vars.executionId

}]

set-variable.value:
#[ (vars.recipientDecisions filter ($.outcome == 'ELIGIBLE')) flatMap (decision) -> do { var customer = (vars.customerRecords filter ($.customer_id == decision.customer_id))[0] default {}
var template = (vars.campaignTemplates filter ($.channel == decision.channel))[0] default {}
var offer = '10% off' var timezone = customer.timezone default 'UTC' var localNow = now() >> timezone var minuteOfDay = (localNow.hour * 60) + localNow.minutes var startMinute = 9 * 60 var endMinute = 21 * 60 var deferred = minuteOfDay < startMinute or minuteOfDay >= endMinute var minutesUntilAllowed = if (minuteOfDay < startMinute) startMinute - minuteOfDay else (24 * 60 - minuteOfDay) + startMinute var sendAt = if (deferred) now() + (minutesUntilAllowed * |PT1M|) else now()
var personalizedBody = ((template.message_body default '') replace /\{\{customer_name\}\}/ with (customer.customer_name default 'Customer')) replace /\{\{campaign_name\}\}/ with (vars.campaign.campaign_name default 'Campaign') replace /\{\{offer\}\}/ with offer
var personalizedSubject = ((template.subject default '') replace /\{\{customer_name\}\}/ with (customer.customer_name default 'Customer')) replace /\{\{campaign_name\}\}/ with (vars.campaign.campaign_name default 'Campaign') replace /\{\{offer\}\}/ with offer
--- if (!isEmpty(template)) [{ customer_id: decision.customer_id, customer_name: customer.customer_name, timeZone: timezone, channel: decision.channel, recipient: if (decision.channel == 'EMAIL') customer.email else if (decision.channel == 'SMS') customer.phone else customer.push_token, subject: personalizedSubject, message: personalizedBody, deferred: deferred, scheduledSendAt: sendAt, status: if (deferred) 'DEFERRED' else 'PERSONALIZED' }] else [] } ]

db:update.db:input-parameters:
#[{
                        queuedCount: vars.queuedCount,
                        deferredCount: vars.deferredCount,
                        executionId: vars.executionId
                    }]
